add_filter( 'woocommerce_get_price_html', 'perfectpixel_logged_out_price_html', 999 );
add_filter( 'woocommerce_is_purchasable', 'perfectpixel_logged_out_purchasable', 999 );
add_filter( 'woocommerce_variation_is_purchasable', 'perfectpixel_logged_out_purchasable', 999 );
add_action( 'init', 'perfectpixel_logged_out_remove_forms' );

function perfectpixel_logged_out_price_html( $html ) {
	if ( is_user_logged_in() || is_admin() ) {
		return $html;
	}
	return '<a class="perfectpixel-login-for-price" href="' . esc_url( wc_get_page_permalink( 'myaccount' ) ) . '">' . esc_html( '{{login_price_text}}' ) . '</a>';
}

function perfectpixel_logged_out_purchasable( $purchasable ) {
	return is_user_logged_in() ? $purchasable : false;
}

// Variable products would still show their dropdowns; remove the forms entirely.
function perfectpixel_logged_out_remove_forms() {
	if ( ! is_user_logged_in() ) {
		remove_action( 'woocommerce_single_product_summary', 'woocommerce_template_single_add_to_cart', 30 );
		remove_action( 'woocommerce_after_shop_loop_item', 'woocommerce_template_loop_add_to_cart', 10 );
	}
}
